import { Accordion, Box, Separator, Tag, Text } from "@chakra-ui/react";
import { useCallback } from "react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import { type ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface AgentEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const AgentEventInfo = ({ event, onClose }: AgentEventInfoProps) => {
  const agentName = event.agentId ?? event.name ?? "agent";
  const flowId = event.flowId || event.metadata?.active_flow;
  const description = event.metadata?.description || "-";
  const tools = event.metadata?.mcp_tools || [];
  const excludedTools = event.metadata?.excluded_mcp_tools || [];
  const exitConditions = event.metadata?.exit_conditions;

  const toolTagStyles = {
    mr: "1",
    maxWidth: "80",
  };

  const renderTools = useCallback(
    (tools: string[]) => (
      <Box>
        {tools.map((tool) => (
          <Tag.Root key={tool} size="xl" variant="subtle" rounded="full" css={toolTagStyles}>
            <Tag.Label>{tool}</Tag.Label>
          </Tag.Root>
        ))}
      </Box>
    ),
    // ignoring because it's not important :)
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  return (
    <DetailView title="Sub-agent event details" onClose={onClose}>
      <InfoField label="Name">
        <Text textStyle="sm" wordBreak="break-all">
          {agentName}
        </Text>
      </InfoField>

      <InfoField label="Description">
        <Text textStyle="sm">{description}</Text>
      </InfoField>

      {!!tools.length && <InfoField label="Tools">{renderTools(tools)}</InfoField>}

      {!!excludedTools.length && (
        <InfoField label="Excluded tools">{renderTools(excludedTools)}</InfoField>
      )}

      {!tools.length && !excludedTools.length && (
        <InfoField label="Tools">
          <Text textStyle="sm" wordBreak="break-all">
            All server tools available
          </Text>
        </InfoField>
      )}

      {flowId && (
        <InfoField label="Trigger">
          <Text textStyle="sm" wordBreak="break-all">
            This sub-agent was triggered by flow {flowId}
          </Text>
        </InfoField>
      )}

      <Separator mt="2" />

      {exitConditions && (
        <Accordion.Root collapsible multiple>
          <EventAccordionItem title="Exit conditions" value="exit-conditions">
            <RasaCodeBlock
              code={exitConditions.map((condition: string) => `- ${condition}`).join("\n")}
              data-testid="agent-exit-conditions"
            />
          </EventAccordionItem>
        </Accordion.Root>
      )}

      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event info" value="event-info">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
